CREATE TABLE "public"."Exam" ("id" TEXT NOT NULL, "title" TEXT NOT NULL DEFAULT 'MCQ Test', "branchCourseId" TEXT NOT NULL, "moduleId" TEXT NOT NULL, "facultyId" TEXT NOT NULL, "marksPerQuestion" INTEGER NOT NULL, "totalQuestions" INTEGER NOT NULL, "totalMarks" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'SCHEDULED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Exam_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public"."ExamSchedule" ("id" TEXT NOT NULL, "examId" TEXT NOT NULL, "branchBatchId" TEXT NOT NULL, "testDate" TEXT NOT NULL, "startTime" TEXT NOT NULL, "endTime" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'SCHEDULED', CONSTRAINT "ExamSchedule_pkey" PRIMARY KEY ("id"), CONSTRAINT "ExamSchedule_examId_branchBatchId_key" UNIQUE ("examId", "branchBatchId"));
CREATE TABLE "public"."ExamQuestion" ("id" TEXT NOT NULL, "examId" TEXT NOT NULL, "question" TEXT NOT NULL, "optionA" TEXT NOT NULL, "optionB" TEXT NOT NULL, "optionC" TEXT NOT NULL, "optionD" TEXT NOT NULL, "correctAnswer" TEXT NOT NULL, "questionOrder" INTEGER NOT NULL, CONSTRAINT "ExamQuestion_pkey" PRIMARY KEY ("id"), CONSTRAINT "ExamQuestion_examId_questionOrder_key" UNIQUE ("examId", "questionOrder"));
CREATE TABLE "public"."ExamAttempt" ("id" TEXT NOT NULL, "examId" TEXT NOT NULL, "scheduleId" TEXT NOT NULL, "branchStudentId" TEXT NOT NULL, "studentUserId" TEXT, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "submittedAt" TIMESTAMP(3), "timeTakenSeconds" INTEGER, "status" TEXT NOT NULL DEFAULT 'IN_PROGRESS', "totalQuestions" INTEGER NOT NULL, "attemptedQuestions" INTEGER NOT NULL DEFAULT 0, "correctAnswers" INTEGER NOT NULL DEFAULT 0, "wrongAnswers" INTEGER NOT NULL DEFAULT 0, "unansweredQuestions" INTEGER NOT NULL DEFAULT 0, "totalMarks" INTEGER NOT NULL, "obtainedMarks" INTEGER NOT NULL DEFAULT 0, "percentage" DOUBLE PRECISION NOT NULL DEFAULT 0, CONSTRAINT "ExamAttempt_pkey" PRIMARY KEY ("id"), CONSTRAINT "ExamAttempt_scheduleId_branchStudentId_key" UNIQUE ("scheduleId", "branchStudentId"));
CREATE TABLE "public"."ExamAnswer" ("id" TEXT NOT NULL, "attemptId" TEXT NOT NULL, "questionId" TEXT NOT NULL, "selectedAnswer" TEXT, "isCorrect" BOOLEAN NOT NULL DEFAULT false, "marksAwarded" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "ExamAnswer_pkey" PRIMARY KEY ("id"), CONSTRAINT "ExamAnswer_attemptId_questionId_key" UNIQUE ("attemptId", "questionId"));
CREATE INDEX "Exam_facultyId_idx" ON "public"."Exam"("facultyId"); CREATE INDEX "Exam_branchCourseId_idx" ON "public"."Exam"("branchCourseId"); CREATE INDEX "Exam_moduleId_idx" ON "public"."Exam"("moduleId"); CREATE INDEX "ExamSchedule_branchBatchId_testDate_idx" ON "public"."ExamSchedule"("branchBatchId", "testDate"); CREATE INDEX "ExamSchedule_examId_idx" ON "public"."ExamSchedule"("examId"); CREATE INDEX "ExamQuestion_examId_idx" ON "public"."ExamQuestion"("examId"); CREATE INDEX "ExamAttempt_branchStudentId_idx" ON "public"."ExamAttempt"("branchStudentId"); CREATE INDEX "ExamAttempt_examId_idx" ON "public"."ExamAttempt"("examId"); CREATE INDEX "ExamAttempt_scheduleId_idx" ON "public"."ExamAttempt"("scheduleId"); CREATE INDEX "ExamAttempt_studentUserId_idx" ON "public"."ExamAttempt"("studentUserId"); CREATE INDEX "ExamAnswer_attemptId_idx" ON "public"."ExamAnswer"("attemptId"); CREATE INDEX "ExamAnswer_questionId_idx" ON "public"."ExamAnswer"("questionId");
ALTER TABLE "public"."Exam" ADD CONSTRAINT "Exam_branchCourseId_fkey" FOREIGN KEY ("branchCourseId") REFERENCES "public"."BranchCourse"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "public"."Exam" ADD CONSTRAINT "Exam_moduleId_fkey" FOREIGN KEY ("moduleId") REFERENCES "public"."BranchCourseModule"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "public"."Exam" ADD CONSTRAINT "Exam_facultyId_fkey" FOREIGN KEY ("facultyId") REFERENCES "public"."User"("id") ON UPDATE CASCADE;
ALTER TABLE "public"."ExamSchedule" ADD CONSTRAINT "ExamSchedule_examId_fkey" FOREIGN KEY ("examId") REFERENCES "public"."Exam"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "public"."ExamSchedule" ADD CONSTRAINT "ExamSchedule_branchBatchId_fkey" FOREIGN KEY ("branchBatchId") REFERENCES "public"."BranchBatch"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."ExamQuestion" ADD CONSTRAINT "ExamQuestion_examId_fkey" FOREIGN KEY ("examId") REFERENCES "public"."Exam"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."ExamAttempt" ADD CONSTRAINT "ExamAttempt_examId_fkey" FOREIGN KEY ("examId") REFERENCES "public"."Exam"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "public"."ExamAttempt" ADD CONSTRAINT "ExamAttempt_scheduleId_fkey" FOREIGN KEY ("scheduleId") REFERENCES "public"."ExamSchedule"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "public"."ExamAttempt" ADD CONSTRAINT "ExamAttempt_branchStudentId_fkey" FOREIGN KEY ("branchStudentId") REFERENCES "public"."BranchStudent"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "public"."ExamAttempt" ADD CONSTRAINT "ExamAttempt_studentUserId_fkey" FOREIGN KEY ("studentUserId") REFERENCES "public"."User"("id") ON UPDATE CASCADE;
ALTER TABLE "public"."ExamAnswer" ADD CONSTRAINT "ExamAnswer_attemptId_fkey" FOREIGN KEY ("attemptId") REFERENCES "public"."ExamAttempt"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "public"."ExamAnswer" ADD CONSTRAINT "ExamAnswer_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "public"."ExamQuestion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
